"""Tests of ``rustorb.DynamicAny`` (#40) with code generated by
``rustorb-idl -bpython``: DynAnys of generated types, valuetypes with
sharing and cycles, truncation, and the classes and exceptions of the
mapping. The cases of interop/impls/rustorbpy/dynany-probe cover the rest
of the operations.

Without the native module or idl_parser the tests are skipped, unless
``RUSTORB_REQUIRE_NATIVE`` is set (as in CI).
"""

import os
import sys
import tempfile
import unittest

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.normpath(os.path.join(HERE, "..", ".."))
for p in (os.path.join(ROOT, "python"), os.path.join(ROOT, "crates", "rustorb-codegen", "python")):
    if p not in sys.path:
        sys.path.insert(0, p)

from rustorb import CORBA, DynamicAny  # noqa: E402

try:
    from rustorb_idl import cli
    import idl_parser  # noqa: F401
except ImportError:
    cli = None

MISSING = None
if CORBA._native is None:
    MISSING = "the native module is not built (python/build-native.sh)"
elif cli is None:
    MISSING = "idl_parser is not importable"
if MISSING and os.environ.get("RUSTORB_REQUIRE_NATIVE"):
    raise ImportError(MISSING)

A = V = None
orb = factory = None


def setUpModule():
    global A, V, orb, factory
    if MISSING:
        raise unittest.SkipTest(MISSING)
    out = tempfile.mkdtemp(prefix="rustorb-dynany-test-")
    idl_dir = os.path.join(ROOT, "interop", "idl")
    for idl in ("AnyTest.idl", "ValueTest.idl"):
        if cli.main(["-bpython", "-C", out, "-I" + idl_dir, os.path.join(idl_dir, idl)]) != 0:
            raise AssertionError("rustorb-idl failed for %s" % idl)
    sys.path.insert(0, out)
    import AnyTest
    import ValueTest

    A, V = AnyTest, ValueTest
    orb = CORBA.ORB_init([], "dynany")
    factory = orb.resolve_initial_references("DynAnyFactory")


class DynAnyTest(unittest.TestCase):
    def test_factory(self):
        self.assertIsInstance(factory, DynamicAny.DynAnyFactory)
        self.assertIn("DynAnyFactory", orb.list_initial_services())
        self.assertRaises(CORBA.ORB.InvalidName, orb.register_initial_reference,
                          "DynAnyFactory", factory)

    def test_classes(self):
        for tc, cls in [
            (A._tc_Point, DynamicAny.DynStruct),
            (A._tc_Oops, DynamicAny.DynStruct),
            (A._tc_Choice, DynamicAny.DynUnion),
            (A._tc_Shade, DynamicAny.DynEnum),
            (A._tc_LongSeq, DynamicAny.DynSequence),
            (A._tc_ShortArray, DynamicAny.DynArray),
            (A._tc_Money, DynamicAny.DynFixed),
            (A._tc_Count, DynamicAny.DynAny),
            (V._tc_Point, DynamicAny.DynValue),
            (V._tc_LongBox, DynamicAny.DynValueBox),
        ]:
            d = factory.create_dyn_any_from_type_code(tc)
            self.assertIs(type(d), cls, tc)
            self.assertTrue(d.type().equal(tc))
            d.destroy()
        self.assertRaises(DynamicAny.DynAnyFactory.InconsistentTypeCode,
                          factory.create_dyn_any_from_type_code, CORBA.TC_Principal)

    def test_round_trip(self):
        node = A.Node("root", [A.Node("a", []), A.Node("b", [A.Node("c", [])])])
        for a in [
            CORBA.Any(A._tc_Node, node),
            CORBA.Any(A._tc_Choice, A.Choice(3, "three")),
            CORBA.Any(A._tc_Octets, b"\x00\xff"),
            CORBA.Any(A._tc_Money, CORBA.fixed("-123.45")),
            CORBA.Any(A._tc_Shade, A.DIM),
            CORBA.Any(CORBA.TC_any, CORBA.Any(A._tc_Point, A.Point(1, 2.5))),
            CORBA.Any(A._tc_Oops, A.Oops("bad", 3)),
        ]:
            got = factory.create_dyn_any(a).to_any()
            self.assertTrue(got.typecode().equal(a.typecode()))
            self.assertEqual(repr(got.value()), repr(a.value()))

    def test_struct(self):
        d = factory.create_dyn_any_from_type_code(A._tc_Point)
        d.insert_long(4)
        d.next()
        d.insert_double(0.5)
        self.assertEqual(d.current_member_name(), "y")
        self.assertIs(d.current_member_kind(), CORBA.tk_double)
        p = d.to_any().value()
        self.assertIsInstance(p, A.Point)
        self.assertEqual((p.x, p.y), (4, 0.5))
        self.assertRaises(DynamicAny.DynAny.TypeMismatch, d.insert_long, 1)
        members = d.get_members()
        self.assertEqual([m.id for m in members], ["x", "y"])
        members[0].value = CORBA.Any(CORBA.TC_long, 9)
        d.set_members(members)
        self.assertEqual(d.to_any().value().x, 9)
        pairs = d.get_members_as_dyn_any()
        pairs[1].value.insert_double(7.0)
        self.assertEqual(d.to_any().value().y, 7.0)

    def test_union_and_enum(self):
        d = factory.create_dyn_any_from_type_code(A._tc_Choice)
        disc = factory.create_dyn_any_from_type_code(CORBA.TC_long)
        disc.insert_long(3)
        d.set_discriminator(disc)
        d.member().insert_string("three")
        self.assertIs(d.discriminator_kind(), CORBA.tk_long)
        c = d.to_any().value()
        self.assertEqual((c._d, c._v), (3, "three"))
        e = factory.create_dyn_any_from_type_code(A._tc_Shade)
        e.set_as_string("DIM")
        self.assertIs(e.to_any().value(), A.DIM)
        self.assertRaises(DynamicAny.DynAny.InvalidValue, e.set_as_string, "PINK")

    def test_sequences(self):
        d = factory.create_dyn_any_from_type_code(A._tc_LongSeq)
        d.insert_long_seq([1, 2, 3])
        self.assertEqual(d.get_long_seq(), [1, 2, 3])
        d.set_length(4)
        self.assertEqual(d.to_any().value(), [1, 2, 3, 0])
        d.set_elements([CORBA.Any(CORBA.TC_long, 5)])
        self.assertEqual([a.value() for a in d.get_elements()], [5])
        o = factory.create_dyn_any_from_type_code(A._tc_Octets)
        o.insert_octet_seq(b"ab")
        self.assertEqual(o.to_any().value(), b"ab")

    def test_any_and_typecode(self):
        d = factory.create_dyn_any_from_type_code(CORBA.TC_any)
        inner = factory.create_dyn_any_from_type_code(A._tc_Point)
        inner.insert_long(2)
        d.insert_dyn_any(inner)
        self.assertTrue(d.get_dyn_any().equal(inner))
        self.assertEqual(d.get_any().value().x, 2)
        t = factory.create_dyn_any_from_type_code(CORBA.TC_TypeCode)
        t.insert_typecode(A._tc_Node)
        self.assertTrue(t.get_typecode().equal(A._tc_Node))

    def test_valuetypes(self):
        n = V.Node(1, None)
        n.next = n
        d = factory.create_dyn_any(CORBA.Any(V._tc_Node, n))
        self.assertFalse(d.is_null())
        d.seek(1)
        self.assertTrue(d.current_component()._is_equivalent(d))
        d.rewind()
        d.insert_long(5)
        got = d.to_any().value()
        self.assertEqual(got.id, 5)
        self.assertIs(got.next, got)
        d.destroy()
        self.assertRaises(CORBA.OBJECT_NOT_EXIST, d.component_count)

        box = factory.create_dyn_any_from_type_code(V._tc_LongBox)
        self.assertTrue(box.is_null())
        box.set_boxed_value(CORBA.Any(CORBA.TC_long, 4))
        self.assertEqual(box.get_boxed_value().value(), 4)

        holder = factory.create_dyn_any_from_type_code(V._tc_Pair)
        p = V.Point(1, 2)
        holder.insert_val(p)
        holder.next()
        holder.insert_val(p)
        pair = holder.to_any().value()
        self.assertEqual((pair.first.x, pair.first.y), (1, 2))

    def test_truncation(self):
        p3 = V.Point3(1, 2, 3, "label")
        a = CORBA.Any(V._tc_Point, p3)
        d = factory.create_dyn_any(a)
        self.assertEqual(d.component_count(), 2)
        self.assertIs(type(d.to_any().value()), V.Point)
        self.assertRaises(DynamicAny.MustTruncate,
                          factory.create_dyn_any_without_truncation, a)


if __name__ == "__main__":
    unittest.main()
